	/** Static SVG markup (no user data inside). */
	public static function get( string $name, int $size = 20 ): string {
		if ( isset( self::RAW[ $name ] ) ) {
			return sprintf( self::RAW[ $name ], $size );
		}
		if ( ! isset( self::PATHS[ $name ] ) ) {
			return '';
		}
		return '<svg class="tbf-ic tbf-ic--' . $name . '" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' . self::PATHS[ $name ] . '</svg>';
	}

	public static function out( string $name, int $size = 20 ): void {
		echo self::get( $name, $size ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- static SVG.
	}
